DocumentHandler.prototype.loadDocumentFromArguments = function (filePath) {
    var ext = path.extname(filePath);
    //alert("loadDocument 2"); <--for me to identify which loadDocumentFromArguments are calling
    var handler = this.handlerRegistry[ext];
    if (handler && handler.loadDocument) {
        var thiz = this;
        if (!fs.existsSync(filePath)) {
            callback({
                error: FileHandler.ERROR_NOT_FOUND,
                message: "File doesn't exist"
            });

            return;
        };

        ApplicationPane._instance.busy();
 
        //MISSING THESE 2 LINES
        this.controller.applicationPane.pageListView.restartFilterCache(); //<-- copy from another function with callback
        this.resetDocument();

        handler.loadDocument(filePath)
            .then(function () {
                thiz.controller.modified = false;
                ApplicationPane._instance.unbusy();
            })
            .catch(function (err) {
                thiz.controller.modified = false;
                ApplicationPane._instance.unbusy();
            });
